"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

P1 v0.4 references (plan 6.5; report only, never part of a choice). Fixed rules, no settings.

  voxturn   VoxTurn alone (as v0.3): R respond iff VoxTurn's eot "yes" >= 0.8; S stop iff a line just ended and
            VoxTurn's intent says interrupt (P(interrupt) >= 0.5), else continue. No speaker tags, no sounds.
  noenv     The usual environment-blind gatekeeper: S stop when the user (by speaker tag) has just said a line, unless
            VoxTurn judges it a backchannel (P(backchannel) >= 0.5); continue when nobody spoke. R respond to every
            line the speaker tag gives to the user when VoxTurn's eot "yes" >= 0.8; lines tagged not the user: not.
  copy      Copy the previous point's (gold) answer in episodes (first point: respond, continue); single-line units:
            always respond and continue. Shows how much state carry-over alone explains.
Decisions are written as {point id: {"S": ..., "R": ...}}, S where the assistant is talking, R where a line ended.
usage: python -X utf8 scripts/p1v4_refs.py dev <out_dir>
"""
import json
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_context as C  # noqa: E402
import p1v4_data as D  # noqa: E402

FEATS = "data/p1v4/feats"


def main(which, out_dir):
    os.makedirs(out_dir, exist_ok=True)
    rows = D.load_rows(which)
    ctx = C.Context(which)
    vt = json.load(open(f"{FEATS}/voxturn_{which}.json"))
    col = {c: i for i, c in enumerate(vt["_columns"])}
    out = {"voxturn": {}, "noenv": {}, "copy": {}}
    for r in rows:
        order = sorted(r["points"], key=lambda q: q["t"])
        for i, p in enumerate(r["points"]):
            pid = f"{r['unit']}|{r['version']}|{p['k']}"
            v = vt[pid]
            line = p.get("line")
            talking = bool(p.get("assistant_speaking")) or p["kind"] in ("S", "RS")   # S asked (as p1v4_situation)
            _, _, tags, _ = ctx.point(r, p["k"])
            user = bool(line) and tags.get(line) == "user"
            eot = v[col["eot:yes"]] >= 0.8
            d1, d2, d3 = {}, {}, {}
            if talking:
                d1["S"] = "stop" if line and v[col["intent:interrupt"]] >= 0.5 else "continue"
                d2["S"] = "stop" if user and v[col["intent:backchannel"]] < 0.5 else "continue"
            if line:
                d1["R"] = "respond" if eot else "not"
                d2["R"] = "respond" if user and eot else "not"
            j = order.index(p)
            prev = order[j - 1]["gold"] if (r["part"] == "episode" and j) else {}
            if talking:
                d3["S"] = prev.get("S") or "continue"
            if line:
                d3["R"] = prev.get("R") or "respond"
            out["voxturn"][pid], out["noenv"][pid], out["copy"][pid] = d1, d2, d3
    for k, dec in out.items():
        json.dump(dec, open(os.path.join(out_dir, f"{k}_decisions_{which}.json"), "w"))
    print({k: len(v) for k, v in out.items()})


if __name__ == "__main__":
    main(*sys.argv[1:3])
